package com.campusiq.platform.client; import com.fasterxml.jackson.annotation.JsonIgnoreProperties; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient;
@Component public class LeetCodeClient {private final RestClient http; public LeetCodeClient(RestClient.Builder b,@Value("${platform.leetcode.base-url}")String url){http=b.baseUrl(url).build();} public Profile profile(String u){return get("/"+u,Profile.class);} public Solved solved(String u){return get("/"+u+"/solved",Solved.class);} public Contest contest(String u){return get("/"+u+"/contest",Contest.class);} private <T>T get(String path,Class<T> type){try{return http.get().uri(path).retrieve().body(type);}catch(Exception e){throw new PlatformClientException("LeetCode is unavailable or returned an invalid response",e);}} @JsonIgnoreProperties(ignoreUnknown=true) public record Profile(String username,String name,String avatar,Long ranking,Long reputation,String errors){} @JsonIgnoreProperties(ignoreUnknown=true) public record Solved(Integer solvedProblem,Integer easySolved,Integer mediumSolved,Integer hardSolved){} @JsonIgnoreProperties(ignoreUnknown=true) public record Contest(Double contestRating,Long contestRanking,Double contestTopPercent){} }
